def B(topic, label, why):
    """A Baseline NLP topic, linked from a loop page."""
    return {"url": "../BASELINE.html#/nlp/" + topic, "label": "Baseline: " + label, "why": why}


def R(*keys, extra=None):
    """A question's reading: Baseline and repo links first (extra), then shared entries by key."""
    return {"read": (extra or []) + [_S[k] for k in keys], "figs": [], "sdLinks": []}


QA = [
    {"group": "Conversation design", "blurb": "How the conversation itself is built: errors, confirmation, repair, handoff, voice and chat. Taught in wc28.", "items": [
        {"q": "How do you design the conversation for a new use case?", "short": "Designing for task completion",
         "tests": "Do you start from users' real tasks and the failure paths, or from a happy-path script?",
         "a": ["I start from the tasks people actually bring, ranked by volume and by the cost of getting them wrong, from logs if there are any. For the top ones I write sample dialogs and read them out loud, because a prompt that reads fine often sounds wrong spoken.",
               "Then I write the failure paths before building anything: what happens on no-match, on silence, on a backend error, when the user changes their mind, when they want a person. Pretty much every bad assistant I've seen had a good happy path and nothing else.",
               "A couple of rules I'd hold to: accept over-answering, so someone who gives the date and the city at once skips both questions, and ask for information in the order people naturally know it. In MockFlow-AI the conversation runs in stages, and I designed each stage's way out before its way in."],
         "land": "Top tasks from real logs, sample dialogs out loud, then every failure path before building.",
         "probes": ["How do you decide what's in scope for version one?", "What's a persona for, in an enterprise bot?", "How long should a voice menu be?"],
         "parts": [{"title": "The failure paths to write first",
                    "items": ["**No-match:** the input wasn't understood.", "**No-input:** silence on voice, nothing typed on chat.", "**System error:** a webhook times out, a backend says no.",
                              "**Correction:** the user changes an earlier answer.", "**Digression:** a side question, then back to the task.", "**Handoff:** the user asks for a person, or the bot should give up.",
                              "**Out of scope:** something the assistant doesn't do, said kindly with a way out."]},
                   {"title": "Rules of thumb",
                    "items": ["Highest-volume intents at the top level; no voice menu longer than 3 to 5 options.", "Accept over-answering: Dialogflow CX prefills form parameters from the matched intent, and Rasa's collect steps can skip a question already answered.",
                              "Persona: Google's recipe is four to six traits, an archetype and a one-paragraph description. In an enterprise bot it's mostly a style guide for the copy and the prompt, and it settles whether the bot says 'I' and what it says when asked 'are you a bot?'"]}],
         "notes": ["Rasa's conversation-driven development is the same loop after launch: review real conversations, tag them, fix in batches."],
         "swaps": [{"when": "If they ask about personas", "line": "I'd keep it short: a handful of traits and a paragraph, used as the style guide for every prompt and line of copy. The point isn't to pass as human; it's that the assistant sounds like one consistent, helpful person."}],
         "learn": R("w28", "g_persona", "rasa_cdd", extra=[B("conversation-design", "conversation design", "The topic, with links to the rest of the field."), _S["va"]])},

        {"q": "How do you handle no-match and no-input?", "short": "No-match and no-input",
         "tests": "The most common event in any assistant, handled with care.",
         "a": ["I count errors per state and escalate the help. The first miss gets a short rephrase, not the same prompt repeated. The second adds options or an example. After about two failures, I offer a way out: a person, another channel, or a menu. Google's and Alexa's guides say pretty much the same thing.",
               "For no-input I don't say 'I didn't hear you'; I rephrase and offer choices. And every message is specific to the state. A global 'Sorry, I didn't get that' is the line people quote when they complain about a bot.",
               "In Dialogflow CX this maps to the numbered no-match and no-input handlers on a flow, page or parameter. On alfred_'s voice agent the idle check-ins and the graceful exit are in code, not left to the model. And I review no-match by page every week, because it points at design gaps and NLU gaps."],
         "land": "Count per state, escalate the help, always a way out; review no-match by page.",
         "probes": ["What's the difference between no-match and a system error?", "When do you hand off instead of reprompting?", "How do you know your reprompts work?"],
         "parts": [{"title": "Three kinds of error",
                    "items": ["**No-input:** silence. A first-class event on voice.", "**No-match:** heard, not understood.", "**System error:** understood, but the backend failed. Say so, and don't make the user repeat themselves."]}],
         "notes": ["Don't blame the user and don't over-apologise. One short apology with the rephrase is enough.",
                   "Measure it: no-match rate per page, and how many sessions recover after the first reprompt."],
         "swaps": [{"when": "If they ask for the Dialogflow CX specifics", "line": "Numbered event handlers, sys.no-match-1 to 6 and sys.no-input-1 to 6, scoped to the flow, the page or a parameter, plus reprompt handlers on form parameters for invalid input."}],
         "learn": R("w28", "g_err", "alexa_err", "cx_handler", extra=[B("conversation-design", "conversation design", "Errors and reprompts.")])},

        {"q": "Explicit or implicit confirmation: when do you use which?", "short": "Confirmation",
         "tests": "Judgement about risk versus friction.",
         "a": ["Implicit is the default: 'Booking a table for two at seven', and the user corrects if it's wrong. Explicit yes-or-no is for actions that are expensive or can't be undone: payments, deletions, sending something on someone's behalf, names and addresses.",
               "I think the rule is: confirm in proportion to the cost of being wrong times the chance of being wrong. So low confidence raises it too. A misheard name on a voice call gets read back even if the action is cheap.",
               "That's how alfred_'s decision layer works. Every candidate action gets one of five verdicts, silent, notify, confirm, clarify or refuse, by deterministic risk scoring. Confirm and clarify are rules, not something the model chooses. Over-confirming has a cost too, so I'd watch turn count and drop-off."],
         "land": "Cost of being wrong times chance of being wrong; implicit by default, explicit for the irreversible.",
         "probes": ["What does over-confirmation cost?", "How does ASR confidence change it?", "Who decides, the model or code?"],
         "notes": ["Lex returns transcription confidence and up to three alternative transcriptions; its docs suggest comparing close candidates (John vs Juan) against a database before asking.",
                   "Cognigy builds the middle band into its thresholds: between reconfirmation and confidence it asks 'did you mean X?'"],
         "swaps": [{"when": "If they ask how alfred_ decides", "line": "Code scores the risk of the action, not the model's opinion of it. A send or a delete can't happen without the person confirming, whatever the model thinks."}],
         "learn": R("w28", "g_conf", "lex_asr", extra=[B("conversation-design", "conversation design", "Confirmation.")])},

        {"q": "How do you handle ambiguity, corrections and digressions?", "short": "Repair",
         "tests": "What happens off the happy path, where most bots fail.",
         "a": ["Ambiguity first: when the top two intents are close, I ask a short closed question, 'Do you mean the card or the account?', rather than guessing. Lex's docs give the example: 0.75 against 0.72 is ambiguous, 0.95 against 0.65 isn't.",
               "Corrections: detect that the user is changing an earlier value, update it, and rerun only the steps that depended on it, with an implicit read-back. Digressions: answer the side question and return to where they were. Dialogflow CX does that with route groups that match anywhere; Rasa ships it as patterns.",
               "Rasa's list of patterns is a good checklist even if you're not on Rasa: correction, clarification, cancel, skip a question, chitchat, human handoff, internal error, repeat, silence. I'd test each as its own scenario class, because that's where happy-path bots break."],
         "land": "Ask when the top two are close; corrections rerun only what depended on them; test repair as its own class.",
         "probes": ["How close is 'close' for the top two?", "What must be remembered deterministically?", "How do you test digressions?"],
         "notes": ["The design question for carry-over: what must be remembered for sure (account, order id, authentication state) versus what the model may infer from the transcript. In an LLM stack carry-over is easier but harder to guarantee.",
                   "alfred_'s working memory takes the first kind seriously: the model picks from real items and code attaches the real ids, which made 'a whole class of hallucination structurally impossible, not probabilistically reduced'."],
         "learn": R("w28", "rasa_patterns", "rasa_dev", "cx_flow", extra=[B("dialogue-state", "dialogue state", "Slots carried across turns.")])},

        {"q": "When should the assistant hand off to a human, and how?", "short": "Handoff",
         "tests": "Do you design the exit, or treat it as failure?",
         "a": ["On an explicit request, immediately, with no more attempts. After a second failure on the same thing. For high-stakes or regulated topics. And on frustration signals. Those triggers are designed up front, not discovered.",
               "The how matters more than people think. Pass a short summary, the intent, identifiers, and what was already tried, so the customer doesn't repeat themselves; Twilio's guidance points out that escalation is cold unless someone designs it otherwise. Warm transfer, where the agent is briefed first, for high emotion or urgency.",
               "And handle the case where nobody's available: a callback or a ticket, never a dead end. I'd measure how often customers have to re-explain after transfer, because a bad handoff quietly destroys CSAT."],
         "land": "Designed triggers; a summary, intent, ids and what was tried; never a dead end.",
         "probes": ["What's in the handoff payload?", "Warm or cold?", "Does a handoff count against containment?"],
         "notes": ["Send an AI summary, not a 40-turn transcript; write the outcome back to the customer record."],
         "learn": R("w28", "twilio", extra=[B("conversation-design", "conversation design", "Handoff.")])},

        {"q": "What do you design differently for voice and for chat?", "short": "Voice and chat",
         "tests": "Channel sense, from someone who's built voice.",
         "a": ["Voice has no scanning. So prompts are short with the question last, lists stay at three or fewer, silence and barge-in are first-class events, and ASR errors dominate failure. I'd use N-best transcripts and confirm low-confidence values, and take sensitive digits by DTMF or spelling.",
               "Chat can use buttons and longer answers, and people can scroll back, but they type fragments and misspellings and expect quick replies. Messaging like SMS adds opt-in rules and no custom UI at all, which is alfred_'s main channel.",
               "On voice I've built both sides: alfred_'s voice agent on phone and web, and MockFlow-AI, with Deepgram Nova-2 for speech and Silero for voice activity, under 400 milliseconds end to end. The thing I'd carry over is tuning thresholds and test sets per channel. Voice utterances aren't chat test data."],
         "land": "Voice: short, question last, silence and ASR first-class. Chat: rich, fragmentary, fast. Separate tests per channel.",
         "probes": ["How would you reduce ASR-driven errors?", "Why not reuse chat utterances for voice?", "What about accessibility?"],
         "parts": [{"title": "ASR errors, in order",
                    "items": ["Separate ASR errors from NLU errors first: word error rate and slot error rate on real audio.", "Phrase hints or speech adaptation for domain words; constrained grammars for known-set slots.",
                              "N-best transcripts checked against the database; DTMF or spelling for IDs.", "Re-measure on real audio, never on typed text."]}],
         "notes": ["Accessibility: generous timeouts and 'repeat' or 'slower' on voice; screen-reader friendly chat, plain language, nothing carried only by colour or emoji, an easy path to a person."],
         "learn": R("w28", "lex_asr", extra=[B("conversation-design", "conversation design", "Voice and chat."), {"url": "../BASELINE.html#/audio/voice-agent-pipeline", "label": "Baseline: the voice agent pipeline", "why": "Where ASR, the model and TTS sit."}, {"url": "commure.html#/prep/q-what-s-hard-about-latency-in-a-voice-agent", "label": "Commure page: latency in a voice agent", "why": "Your voice latency answer, already written."}])},

        {"q": "Flows or a generative agent: how do you decide?", "short": "Flows or generative",
         "tests": "Where you put determinism, and why.",
         "a": ["By risk and determinism. Authentication, payments and anything with regulatory consequences stay deterministic: flows, authored topics. Open-ended help and FAQs go to a generative layer with retrieval. In between, a generative layer with approval checkpoints.",
               "Google and Microsoft both describe that layering. Dialogflow CX keeps flows for deterministic work like authentication or payment and uses playbooks for open-ended conversation; Copilot Studio keeps a deterministic layer for irreversible actions. Rasa's CALM goes further: the LLM only translates what the user said into commands, and the business logic stays in flows.",
               "I'd start deterministic on the money paths and widen the generative scope only as the evaluation data supports it. It's the same rule I use at alfred_: the model proposes, code authorises."],
         "land": "Money and regulation in flows, the long tail generative, widened only on evidence. The model proposes, code authorises.",
         "probes": ["What goes in the middle layer?", "How do you stop prompt injection reaching a tool?", "How do you migrate an existing bot?"],
         "notes": ["OWASP's top risks for LLM apps include prompt injection, sensitive information disclosure and excessive agency. Server-side authorisation on every tool, and an explicit confirmation turn for risky ones."],
         "swaps": [{"when": "If they ask how you'd migrate a classic bot", "line": "Inventory intents by volume and success rate, keep the accurate ones with strict flows, move the long tail and FAQs to retrieval or an LLM classifier, run old and new in shadow on logged traffic, compare on the golden set, then shift traffic gradually with a rollback."}],
         "learn": R("w28", "cx_playbook", "copilot", "rasa_du", "owasp", extra=[B("nlu-llm-hybrid", "classic NLU and LLMs together", "The hybrid at depth."), _S["vadd"]])},
    ]},

    {"group": "Intents, entities and the NLU model", "blurb": "The taxonomy, training data, entities, thresholds and dialogue state, and where LLMs change them. Taught in wc29.", "items": [
        {"q": "How would you design the intent taxonomy for, say, a bank assistant?", "short": "Intent taxonomy",
         "tests": "Granularity, consistency and a merge-or-split rule.",
         "a": ["I'd start from call and chat logs and rank tasks by volume and risk, not from the product catalogue. Actions become intents: check balance, dispute a transaction, report a lost card. Products and accounts become entities. Microsoft's CLU guidance puts it well: cancel is one intent and the product is an entity, so you don't build 'cancel product X' as its own intent.",
               "Then route by domain first, accounts, cards, loans, fraud, so each classifier has a manageable label space, with top-priority routes for fraud and 'I want a person'. Flat taxonomies start breaking down past a few hundred intents.",
               "My test for granularity: if two intents get the same flow and the same API call, merge them and use an entity; if the same words need different handling, like a lost card versus a declined card, split them. And I'd validate on a labelled sample of real utterances with a confusion matrix before building any flows."],
         "land": "Actions as intents, things as entities, domain first; merge if same flow and call, split if handling differs.",
         "probes": ["How many intents is too many?", "Who owns the taxonomy?", "How do you stop it drifting as teams add intents?"],
         "parts": [{"title": "Merge or split",
                    "items": ["**Merge** when two intents share a flow and a backend call: one intent plus an entity.", "**Split** when the words are similar but the handling differs.",
                              "**Keep both and ask** when users' words genuinely can't separate them: a disambiguation question when the scores are close.", "**One schema style** across the project: don't model half as action-as-intent and half as information-as-intent."]},
                   {"title": "Past a few hundred intents",
                    "items": ["Route by domain first (Dialogflow CX flows; Microsoft orchestration across CLU and question answering), then classify within it.", "Or head intents plus a modifier entity."]}],
         "learn": R("w29", "clu_bp", extra=[B("intents-entities", "intents and entities", "The modelling, with platform terms side by side."), _S["va"]])},

        {"q": "How many training phrases does an intent need, and where do they come from?", "short": "Training data",
         "tests": "Data quality judgement, not a magic number.",
         "a": ["The platforms give minimums: Dialogflow CX recommends at least 10 to 20 per intent, CLU flags fewer than 15 and wants at least 25 for its out-of-domain setup, Kore.ai says 8 to 10 balanced across intents, and Cognigy's analyzer flags fewer than 5. I'd treat those as floors, not targets.",
               "Quality matters more than count. Balance the classes, because imbalance biases toward the big intents. Vary casing and punctuation. Avoid accidental patterns, like every example starting with 'I want'. Diversify the wording, don't reorder the same words. And source from production logs, not only from the design team, because designers write the way designers talk.",
               "Then a held-out test set that's never trained on and covers every intent. At alfred_ every test case comes from a real production failure, and that's the instinct I'd bring: real users' words are the ground truth."],
         "land": "Platform minimums are floors; balanced, varied, real users' words; a frozen test set.",
         "probes": ["How do you generate examples for a new intent with no traffic?", "Can you use an LLM to write training phrases?", "How do you keep the test set clean?"],
         "notes": ["An LLM can draft examples for a cold start, but they share the model's phrasing. Replace them with real utterances as traffic arrives, and never let generated text into the test set.",
                   "Watch for leakage: the same utterance, or a near duplicate, in train and test."],
         "learn": R("w29", "cx_intent", "clu_bp", "cog_an", extra=[B("intents-entities", "intents and entities", "Training phrases.")])},

        {"q": "How do you model entities and slots?", "short": "Entities and slots",
         "tests": "The right extractor for each kind of value.",
         "a": ["System entities for dates, numbers and emails. Lists with synonyms for closed vocabularies. Regex plus validation for identifiers like order numbers. Learned entities where context decides the meaning. Most platforms let you combine these.",
               "The trap is extractors firing everywhere. CLU's example is a ticket-quantity entity built only on the prebuilt number, which fires on '3 PM'; the fix is to add a learned component and make it required. Roles like origin versus destination need a signal in the data, words like 'from' and 'to'.",
               "For IDs and account numbers I'd use deterministic extraction and validate against the system of record, not ML. That's the same instinct as alfred_'s working memory: the model picks, code attaches the real ids."],
         "land": "System, list, regex, learned: each for its kind; required components stop false fires; IDs are deterministic.",
         "probes": ["How do you handle synonyms?", "How do you validate a slot?", "What about over-answering?"],
         "parts": [{"title": "Entity types across platforms",
                    "items": ["**System or prebuilt:** date, number, email.", "**List with synonyms:** a reference value plus synonyms; Dialogflow CX can auto-generate up to 3 synonyms.",
                              "**Regex:** IDs, order numbers.", "**Learned:** context decides; needs examples.", "**Lex custom slot types:** expand values by ML (the default) or restrict to listed values and synonyms; up to five resolved values come back."]}],
         "learn": R("w29", "cx_entity", "lex_slot", "clu_bp", extra=[B("intents-entities", "intents and entities", "Entities."), B("sequence-labelling", "sequence labelling", "NER under the entity extractor.")])},

        {"q": "What is dialogue state, and how do you track it?", "short": "Dialogue state",
         "tests": "The formal name for what flows and slots do.",
         "a": ["Dialogue state is the structured set of slot values and where the user is in the task, at each turn. Dialogue state tracking is updating it as the conversation goes, and it's measured by joint goal accuracy: the share of turns where every slot is right.",
               "On the platforms it's built in. A Dialogflow CX page is a state, and its form collects required parameters, prefilled from the session or the matched intent. Lex elicits slots through code hooks. Rasa's collect steps fill slots, and CALM adds corrections.",
               "With LLMs it's often function calling: each tool is an intent, its arguments are slots. The FnCTOD paper used that for zero-shot tracking. In MockFlow-AI the state is an explicit state machine, and the model can only move it by calling a transition tool, so it can't drift."],
         "land": "The slots and the position at each turn; joint goal accuracy; pages, slots or tool arguments hold it.",
         "probes": ["Why joint goal accuracy and not per-slot?", "Where does state live in an LLM agent?", "How do you test it?"],
         "notes": ["Joint goal accuracy is strict on purpose: a right intent with one wrong slot still fails the task."],
         "learn": R("w29", "cx_page", "p_fnctod", extra=[B("dialogue-state", "dialogue state", "Tracking, and how it's measured.")])},

        {"q": "How do you set confidence thresholds?", "short": "Thresholds",
         "tests": "Calibration and risk, not a default.",
         "a": ["From evaluation data, not defaults. I'd plot precision and recall, and the cost of a wrong action, against the threshold for each intent family, then pick three bands: act above the high one, confirm or disambiguate in the middle, fall back below.",
               "Cognigy builds exactly that: a confidence threshold, default 0.4, a reconfirmation threshold, default 0.2, and not found below. High-risk intents get a higher bar and an explicit confirmation on top.",
               "And scores are model-specific. Lex says its scores are comparative and may change as the model improves, and CLU needs a retrain and republish after a threshold change. So I recalibrate after every model or training change, and I treat a threshold change as a release."],
         "land": "Three bands from your own data, a higher bar for risky intents, recalibrated after every model change.",
         "probes": ["What if the model is overconfident?", "One threshold or one per intent?", "How do you choose the middle band's width?"],
         "notes": ["CLU warns a model can predict the wrong intent at 1.00 confidence, which makes any threshold useless. That's a calibration problem: temperature scaling, or the platform's newer training configs.",
                   "Lex: you set nluIntentConfidenceThreshold per locale; it returns the top intent and up to four alternates."],
         "learn": R("w29", "cog_thr", "lex_conf", "p_calib", extra=[B("out-of-scope", "out-of-scope detection", "Thresholds as a detector."), B("classification-metrics", "classification metrics", "Precision and recall against a threshold.")])},

        {"q": "Classic NLU or an LLM for intent classification?", "short": "Classic or LLM",
         "tests": "A grounded trade-off, with numbers.",
         "a": ["It depends on the label space and the constraints. For a stable, well-labelled, latency-critical domain, a fine-tuned encoder is faster, cheaper and often as accurate. An LLM wins when the schema changes, labels are few, or out-of-scope detection matters.",
               "One 2026 preprint put numbers on it: a fine-tuned RoBERTa beat Claude Haiku on ATIS, 95.9 to 84.1, and tied on CLINC150, but the LLM was far better at out-of-scope recall, 85.6 to 58.1, and could switch schemas with no retraining. The cost was latency: about 981 milliseconds at p50 against 2.4.",
               "So the usual production answer is hybrid. A fast classifier takes the confident turns and the uncertain ones go to an LLM; an Amazon paper measured that within 2% of the LLM's accuracy with half the latency. At alfred_ the same idea shows up as cost: replacing per-message model calls with a deterministic matcher cut per-user LLM cost about 30%."],
         "land": "Encoder for stable, fast, labelled; LLM for changing schemas and out-of-scope; hybrid in production.",
         "probes": ["How does the router decide it's uncertain?", "What about multi-intent messages?", "How do you evaluate both fairly?"],
         "parts": [{"title": "The numbers, and how sure they are",
                    "items": ["**Decision framework preprint (arXiv 2608.20371, 2026, not yet peer reviewed):** ATIS 95.9 vs 84.1; CLINC150 89.1 vs 88.5; out-of-scope recall 85.6 (LLM) vs 58.1; a fixed classifier scored 0% on an unseen schema; p50 about 981 ms vs 2.4 ms; about $0.25 per 1,000 calls. One data point.",
                              "**Amazon, EMNLP 2024 industry (arXiv 2410.01627):** route to the LLM only when a SetFit classifier is uncertain (Monte Carlo dropout); within 2% of the LLM's accuracy, 50% less latency. A large label space hurts out-of-scope; a two-step method gained over 5% on out-of-scope for Mistral-7B.",
                              "**Its decision rule:** stable, labelled, latency-critical means an encoder; dynamic schemas or out-of-scope-critical means an LLM; noisy ASR means hybrid."]}],
         "notes": ["Whatever the choice, the same evaluation set and the same thresholds for both, or the comparison means nothing.",
                   "Multi-intent ('open an account and send me the details'): classic NLU returns one intent a turn, so you split, queue the detected intents, or let an LLM planner call them in turn, as Copilot Studio's generative orchestration does."],
         "swaps": [{"when": "If they ask how the router knows it's uncertain", "line": "A calibrated confidence with a threshold, the margin between the top two, or, in the Amazon paper, Monte Carlo dropout: run the classifier a few times with dropout on and route when the answers disagree."}],
         "learn": R("w29", "p_decide", "p_hybrid", "copilot", extra=[B("nlu-llm-hybrid", "classic NLU and LLMs together", "Routing between them."), _S["vadd"]])},

        {"q": "How would you add an LLM to an existing Dialogflow bot safely?", "short": "An LLM, added safely",
         "tests": "Incremental, measured change to a live system.",
         "a": ["Start where the risk is lowest: generative fallback on the no-match handlers, or a retrieval-backed answer for FAQs, and keep the flows for transactions. Ground answers in an approved knowledge base, use the banned-phrases list, and remember generative fallback sits outside the CX SLA and falls back to canned text when generation fails.",
               "Before any traffic, a golden test set and an LLM-judge rubric. Then shadow mode, or an experiment on a small share of traffic, watching escalation, CSAT and a reviewed sample for hallucination.",
               "Only then playbooks, for open-ended tasks, with authentication and payments staying in flows. It's how I'd ship anything at alfred_: real cases first, then a small rollout, then wider."],
         "land": "Lowest risk first, evals before traffic, shadow then experiment, flows keep the money paths.",
         "probes": ["What would you measure in the experiment?", "What's in the judge's rubric?", "How do you stop it answering account questions from documents?"],
         "notes": ["I haven't run this on Dialogflow. Say so if asked, then the method."],
         "learn": R("w29", "cx_genfb", "cx_playbook", "cx_exp", extra=[B("nlu-llm-hybrid", "classic NLU and LLMs together", "Generative fallback and playbooks.")])},

        {"q": "How do function calling and tools relate to intents and slots?", "short": "Tools as intents",
         "tests": "Do you see the old and new as one model?",
         "a": ["A tool is an intent with typed arguments, and the arguments are slots. The model fills them against a schema, which gives you zero-shot slot filling and new capabilities without retraining. FnCTOD showed that for dialogue state tracking: 5.6 points of joint goal accuracy for ChatGPT and 14 for GPT-4, with a fine-tuned 13B model comparable to ChatGPT.",
               "The cost is determinism. tau-bench found GPT-4o tool-calling agents solved under half of retail tasks, and passed all eight tries of the same task under 25% of the time. So I keep a deterministic policy layer, validate arguments server side with the same validators as before, and run each test scenario several times.",
               "That's alfred_'s shape: intent classification, a decision layer, then callable tools. And in MockFlow-AI the stage only moves when the model calls the transition tool."],
         "land": "Tools are intents, arguments are slots; flexible but less deterministic, so validate and gate in code.",
         "probes": ["How do you validate arguments?", "What's pass^k?", "How many tools before selection degrades?"],
         "notes": ["Structured output with a JSON schema for extraction; validate with regex, list lookups and database existence checks, the same as classic slots.",
                   "Keep the tool list small with precise descriptions; Copilot Studio says names carry more weight than descriptions when its planner picks."],
         "learn": R("w29", "p_fnctod", "p_tau", extra=[B("nlu-llm-hybrid", "classic NLU and LLMs together", "Function calling as NLU."), {"url": "mphasis.html#/prep/q-how-does-tool-calling-actually-work", "label": "Mphasis page: how tool calling works", "why": "The mechanism, already written."}, {"url": "../CODING.html#structured", "label": "Coding page: structured output and function calling", "why": "The code."}])},

        {"q": "An FAQ intent and a transactional intent keep colliding, like 'my card...'. What do you do?", "short": "FAQ or transaction",
         "tests": "Routing between knowledge and action.",
         "a": ["Use a router with a clear rule: the transactional intent wins when there's an authenticated account context and an action verb; informational questions go to retrieval. When both score close, ask one line: 'Do you want to know about card fees, or do something with your card?'",
               "Keep the account-specific path separate from RAG, so a generic document never answers a question about one person's account. I'd keep an explicit intent for 'needs a transaction' for exactly that reason.",
               "Then test it on a labelled set of near-miss pairs, because those collisions are what the overall accuracy hides."],
         "land": "Action plus account context means transaction; questions mean retrieval; ask when close; test on near-miss pairs.",
         "probes": ["How would you replace dozens of FAQ intents?", "How do you keep retrieval fresh?"],
         "notes": ["Replacing FAQ intents with retrieval over a curated knowledge base is the usual move: Lex has KendraSearchIntent, Dialogflow data stores, Copilot Studio knowledge sources."],
         "learn": R("w29", extra=[B("nlu-llm-hybrid", "classic NLU and LLMs together", "Retrieval for FAQs."), {"url": "../BASELINE.html#/ai/rag", "label": "Baseline: RAG", "why": "Retrieval, grounding and citations."}])},

        {"q": "Which conversational AI platforms do you know, and how do they differ?", "short": "The platforms",
         "tests": "Breadth, and honesty about what you've used.",
         "a": ["Honestly, I haven't shipped on any of them; I've built the NLU layer myself in front of LLM agents. But I've read how each one models the same problem, and they map cleanly.",
               "Dialogflow CX is flows of pages, states with forms, routes and event handlers, now with playbooks and generative fallback on top. Lex is intents and slots with Lambda code hooks, a fallback intent and a test workbench. Microsoft has CLU as the classic NLU, and Copilot Studio, where an LLM planner picks topics and tools. Rasa's CALM uses the LLM only to understand and keeps the logic in flows. Kore.ai scores several engines and ranks them; Cognigy has intent thresholds and an analyzer for weak intents.",
               "What carries over from my work is the underneath: taxonomy, thresholds, fallbacks, state, and error analysis on real transcripts. I'd ask which one you're on and spend my first week in it."],
         "land": "Not shipped on one; know how each models it; the underneath is mine.",
         "probes": ["Which would you pick?", "What do you know about Dialogflow CX in particular?", "How quickly could you be productive?"],
         "parts": [{"title": "One line each",
                    "items": ["**Dialogflow CX:** flows (topics) of pages (states), routes, route groups, event handlers; playbooks for open-ended work; test cases and experiments.",
                              "**Amazon Lex V2:** intents, slots and slot types, Lambda code hooks, confidence threshold, FallbackIntent, KendraSearchIntent, Test Workbench.",
                              "**Microsoft CLU and Copilot Studio:** CLU's intents, entity components and None intent; Copilot Studio's generative orchestration with deterministic, hybrid and generative layers.",
                              "**Rasa CALM:** the LLM emits commands (start flow, set slot, correct, clarify, hand off); flows hold the logic.",
                              "**Kore.ai XO:** several engines (fundamental meaning, ML, knowledge graph) ranked by a resolver; a validation view with confusion matrix and k-fold.",
                              "**Cognigy:** intent thresholds in three bands; an Intent Analyzer for weak and overlapping intents.",
                              "**IBM watsonx Assistant:** not checked; say you'd read current docs before asserting anything."]}],
         "never": ["Never say you've used one. 'I've read how it works' is true; 'I've used it' is not."],
         "learn": R("w29", "cx_flow", "copilot", "rasa_du", "kore_val", extra=[B("intents-entities", "intents and entities", "Platform terms side by side.")])},
    ]},

    {"group": "Error analysis and production", "blurb": "Finding what's wrong in real conversations and improving the assistant safely. Taught in wc30.", "items": [
        {"q": "Two intents keep getting confused. What do you do?", "id": "q-two-intents", "short": "Two intents confused",
         "tests": "Method: evidence first, then the right fix, then a check.",
         "a": ["I'd look at the confusion matrix and then the actual misclassified utterances, not only the F1. The numbers tell you where; the utterances tell you why.",
               "Then decide which case it is. If they're really one intent with different entities, merge them. If they're distinct actions with ambiguous wording, keep both and add contrastive examples, pairs that differ in the one thing that matters. Check the training data for bias too: one intent with twice the examples, or a stray phrase pattern that's doing the classifying. And if users' words genuinely can't separate them, keep both and ask a disambiguation question when the scores are close.",
               "Last, rerun the frozen test set, because a fix often moves the errors to a neighbour. It's how I work on alfred_'s failures: read the real cases, decide whether it's the model, the data or the design, fix that, and check against everything else."],
         "land": "Confusion matrix, then the utterances; merge, split with contrastive examples, or ask; rerun the frozen set.",
         "probes": ["How do you know it's the data and not the model?", "What's a contrastive example?", "What if merging breaks a downstream flow?"],
         "parts": [{"title": "The order",
                    "items": ["**Look:** the confusion matrix's off-diagonal cell, then every utterance in it.", "**Margin:** how close are the top two scores? A low margin is a conflict (Lex: 0.75 vs 0.72).",
                              "**Data:** counts per intent, accidental patterns, mislabelled examples.", "**Decide:** merge, split with contrastive examples, or keep both and disambiguate.",
                              "**Check:** rerun the frozen test set; look at the neighbours."]}],
         "notes": ["Platforms flag this for you: Kore.ai's validation and Cognigy's Intent Analyzer show overlapping intents; Cognigy marks weak intents below 0.6."],
         "learn": R("w30", "clu_eval", "kore_val", "cog_an", extra=[B("error-analysis", "error analysis", "Confusion and overlap."), B("classification-metrics", "classification metrics", "The confusion matrix.")])},

        {"q": "Containment dropped 10% after a release. Walk me through it.", "short": "Containment dropped",
         "tests": "Calm, ordered debugging of a live metric.",
         "a": ["First, is it real? I'd check the metric's definition, the data pipeline and the traffic mix, because a campaign or an outage changes which intents come in.",
               "Then diff by version. Break containment down by intent, channel, flow, page and the traffic's version, and find where it moved. Look at no-match rate, escalation reasons, webhook errors and timeouts, and abandonment by page. If one flow regressed, roll that version back, or cut its experiment traffic, while I read the transcripts to find the cause.",
               "Then make it not happen again: a regression test for the cause, and an alert on that page's no-match or escalation rate. I think the order matters more than any single step: confirm, localise, stop the bleeding, then root cause."],
         "land": "Confirm it's real, localise by version and page, roll back, read transcripts, add a test and an alert.",
         "probes": ["What if it's not the release?", "How fast would you roll back?", "What's your first query?"],
         "notes": ["Dialogflow CX analytics shows no-match, escalation and exit rates by page, and webhook errors and latency: the first place to look on that platform.",
                   "Containment can also drop for a good reason: a fix that stops the bot trapping people. Check repeat contact before calling it a regression."],
         "learn": R("w30", "cx_analytics", extra=[B("error-analysis", "error analysis", "Localising a regression."), B("assistant-metrics", "assistant metrics", "What containment does and doesn't measure.")])},

        {"q": "How do you find the intents you're missing?", "short": "Finding new intents",
         "tests": "Mining production for what the taxonomy doesn't cover.",
         "a": ["Collect the fallback and low-confidence utterances plus the escalated conversations. Embed them, cluster them, with HDBSCAN or k-means, and have an LLM name each cluster for a person to review. Rank by volume times business cost.",
               "For each cluster decide: a new intent, examples for an existing one, examples for the none class, or a content gap for retrieval. Check the proposal against the existing taxonomy first, so the new intent doesn't overlap a neighbour, then validate on a held-out sample.",
               "It's close to what my production failure scanner does at alfred_: read real conversations, separate genuine failures from expected behaviour, and promote the real ones, so the backlog comes from users and not from guesses."],
         "land": "Embed the misses, cluster, name with an LLM, rank by volume and cost, then decide intent, examples or content.",
         "probes": ["Why HDBSCAN over k-means?", "How big must a cluster be to become an intent?", "How do you stop overlap?"],
         "notes": ["HDBSCAN finds clusters of varying density and leaves noise unclustered, so you don't need to guess k; k-means is simpler when you roughly know how many topics to expect."],
         "learn": R("w30", "rasa_cdd", extra=[B("error-analysis", "error analysis", "Mining misses."), B("sentence-embeddings", "sentence embeddings", "What the clustering runs on.")])},

        {"q": "How do you evaluate an NLU model beyond accuracy?", "short": "NLU evaluation",
         "tests": "The full set of metrics, and why each.",
         "a": ["Per-intent precision, recall and F1, with macro and micro averages, so rare intents aren't hidden. A confusion matrix for which ones collide. Entities evaluated separately, span and type, because a right intent with a wrong entity still fails. And the out-of-scope false-accept rate, plus calibration of the confidence.",
               "Then test on production-like data: typos, casing, ASR noise. For voice, word error rate and slot error rate on real audio, not typed text. And at the conversation level, joint goal accuracy, because the task needs every slot right.",
               "I'd report latency too, p50 and p95, and cost per thousand requests, next to a baseline. A metric without the baseline doesn't tell you much."],
         "land": "Per-intent P/R/F1, macro and micro, confusion, entities, out-of-scope, calibration, on production-like data.",
         "probes": ["Macro or micro, and why?", "How do you evaluate entities?", "How big should the test set be?"],
         "notes": ["CLU's worked example has the intent right and the entity span wrong: count those separately.",
                   "With a small test set, report confidence intervals or several seeds before claiming a gain."],
         "learn": R("w30", "clu_eval", extra=[B("classification-metrics", "classification metrics", "Macro, micro, the confusion matrix."), B("assistant-metrics", "assistant metrics", "From turn to conversation.")])},

        {"q": "How do you structure transcript review?", "short": "Transcript review",
         "tests": "A repeatable labelling process, not ad-hoc reading.",
         "a": ["Weekly, sampled by stratum, not only at random: every escalation, abandoned sessions, low-confidence turns, negative feedback, plus a random slice. And whole conversations, because many failures are dialogue failures a per-utterance metric never shows.",
               "Each failed conversation gets one primary cause from a fixed taxonomy, plus the correct intent and entities. A labelling guide with rulings on edge cases, two labellers on a subset to measure agreement, and a gold set.",
               "Every label becomes either a test case or a training example. That's the loop at alfred_: the scanner flags real failures, they become eval cases, and every change runs against them."],
         "land": "Stratified weekly sample, whole conversations, one primary cause each, agreement measured, every label becomes a test.",
         "probes": ["What's in your failure taxonomy?", "How do you measure labeller agreement?", "How many conversations a week?"],
         "parts": [{"title": "One primary cause per failed conversation",
                    "items": ["**ASR error** (voice only).", "**NLU miss:** wrong or no intent.", "**Entity or slot error.**", "**Dialogue logic or design:** wrong path, a trap, no repair.",
                              "**Backend failure or timeout.**", "**Knowledge or content gap.**", "**Policy:** it legitimately can't do that.", "**Abandonment** with no failure signal."]},
                   {"title": "Why one cause",
                    "items": ["The split tells you where to spend: training data, flows, integrations or the product.", "Report it as a share of lost containment."]}],
         "notes": ["Agreement: Cohen's kappa on the double-labelled subset. In MockFlow-AI the judge was calibrated against human grades at weighted kappa 0.82."],
         "learn": R("w30", "rasa_cdd", extra=[B("error-analysis", "error analysis", "The failure taxonomy."), {"url": "coframe.html#/prep/say-now", "label": "Coframe page: the eval harness story", "why": "Real failures become cases: your answer, already written."}])},

        {"q": "Which KPIs do you report, and which ones mislead?", "short": "KPIs",
         "tests": "Knowing what a number hides.",
         "a": ["Containment is useful but easy to game: a wall contains. So I'd report it next to solution rate, where the customer confirms it's resolved, and repeat contact within 24 to 72 hours, because someone who calls back tomorrow wasn't contained.",
               "Then the working metrics: escalation rate by intent, no-match rate by page, task-completion funnels, CSAT by bucket, and handle time for escalated contacts, which should drop if the handoff carries context.",
               "And filter to business conversations first, no greetings, tests or spam. I'd compute resolution from outcomes, not as one minus escalation."],
         "land": "Containment next to solution rate and repeat contact; funnels and per-page rates to act on.",
         "probes": ["How do you measure containment without identity?", "What's a funnel for an intent?", "Which single number would you put on a dashboard?"],
         "parts": [{"title": "Words that get mixed up",
                    "items": ["**Deflection:** conversations handled by the AI alone.", "**Containment:** the customer didn't come back through another channel for the same issue; hard without identity.",
                              "**Automation rate:** workflows completed.", "**Solution rate:** the customer confirms it's resolved.", "(Rasa's split; a vendor blog, but the distinctions are standard.)"]},
                   {"title": "A per-intent funnel",
                    "items": ["Intent recognised, required slots filled, authenticated, backend call succeeded, confirmation shown, completed.", "Dialogflow CX's page view (traffic, no-match, escalation, exit rate) is that funnel per state."]}],
         "learn": R("w30", "rasa_kpi", "cx_analytics", extra=[B("assistant-metrics", "assistant metrics", "Containment and what it hides.")])},

        {"q": "How would you A/B test a change to a flow?", "short": "A/B testing",
         "tests": "Experiment design on a live assistant.",
         "a": ["Version the flow and split live traffic between control and variants; Dialogflow CX experiments take up to four variants with auto-rollout steps and stop conditions. Assign by user or session, consistently, never by turn.",
               "Pre-register one primary metric, task completion, not turn count, and guardrails: escalation, CSAT, repeat contact. Run through full weekly cycles, because Monday traffic isn't Saturday traffic, and check significance before shipping.",
               "One change at a time. And I'd look past the headline: a variant with a lower handoff rate can be worse if people call back the next day."],
         "land": "One change, assign by user, a pre-registered primary metric and guardrails, full weeks.",
         "probes": ["How long would you run it?", "What if the primary and a guardrail disagree?", "How do you test a prompt change the same way?"],
         "notes": ["A prompt or knowledge-base change is a release too: same pipeline, same tests, same experiment."],
         "learn": R("w30", "cx_exp", extra=[B("assistant-metrics", "assistant metrics", "Experiments.")])},

        {"q": "How do you monitor a live assistant for drift?", "short": "Drift",
         "tests": "Knowing what to watch and what a shift means.",
         "a": ["Intent mix, the confidence distribution, fallback and escalation rates by intent, webhook and tool error rates, and for the LLM parts groundedness, refusal rate, cost and latency. Alert on deviation from a rolling baseline, not only on absolute thresholds.",
               "Annotate the dashboards with releases, campaigns and outages, because seasonal and campaign effects are the usual false alarms.",
               "A sudden rise in fallback is one of two things: a new topic, which needs an intent or content, or a regression, which needs a rollback. Reading twenty of the new fallbacks usually tells you which in a few minutes."],
         "land": "Watch the mix and the confidence, alert on a rolling baseline, annotate releases; new topic or regression.",
         "probes": ["What's the difference between data drift and concept drift here?", "How would you detect it with embeddings?"],
         "notes": ["A drop in average confidence with a stable intent mix often means new phrasing: users talk about the same things differently. Embedding the new traffic and comparing it with training data shows it."],
         "learn": R("w30", extra=[B("assistant-metrics", "assistant metrics", "Monitoring."), B("error-analysis", "error analysis", "Fallback spikes.")])},

        {"q": "How do you use an LLM as a judge on conversations, and where does it fail?", "short": "LLM-as-judge",
         "tests": "Using it with its biases in view.",
         "a": ["Give it the full transcript, the tool traces and a rubric, one criterion at a time: task success, policy adherence, groundedness, tone, an unnecessary escalation. Binary or small scales. For pairwise comparisons, randomise the order.",
               "The MT-bench paper found strong judges agreed with humans over 80% of the time, about the human-to-human rate, but with position, verbosity and self-enhancement biases. So I calibrate against a human-labelled set and keep tracking agreement. In MockFlow-AI the judge sat at weighted kappa 0.82 against human grades.",
               "And I don't use a judge where the decision has to be exact. alfred_'s decision layer uses deterministic risk scoring, not LLM-as-judge, because whether to confirm a send can't be a matter of opinion. Judges are for quality; compliance checks stay in code."],
         "land": "Rubric per criterion, small scales, order randomised, calibrated against humans; never the only gate for compliance.",
         "probes": ["How do you know the judge is still right?", "Which bias bites most?", "Pass^k, what is it?"],
         "notes": ["Simulated users (tau-bench) give breadth, but a simulated user is more cooperative than a real one; real transcript replay stays the anchor."],
         "learn": R("w30", "p_mtbench", extra=[B("error-analysis", "error analysis", "Judges on transcripts."), {"url": "zenml-round3.html#/prep/q-how-do-you-decide-what-becomes-an-eval-case-and-is-the-judge", "label": "ZenML page: what becomes an eval case, and is the judge still right", "why": "Your fuller answer on judges, already written."}, {"url": "../BASELINE.html#/ai/llm-as-judge", "label": "Baseline: LLM-as-judge", "why": "The core topic."}])},

        {"q": "How do you test a conversational system before release?", "short": "Testing before release",
         "tests": "Layers of tests, and reliability over a single run.",
         "a": ["Four layers. An NLU test set with metrics. Scripted golden conversations with turn-level expectations; Dialogflow CX test cases check the response, intent, page and flow at each turn and report coverage of transitions and intents. Simulated users for breadth. And a human review sample.",
               "For the LLM parts, a rubric judge calibrated against human labels, and each scenario run several times. tau-bench's pass^k, the chance all k tries succeed, is the honest number: GPT-4o agents passed all eight tries of a retail task under 25% of the time.",
               "Release is gated on a 'never break' suite of high-value and high-risk scenarios, then a canary. At alfred_ the eval harness replays real failures against a frozen copy of the user's world; it's how we signed off a full rewrite of the agent."],
         "land": "NLU set, golden conversations, simulated users, human sample; run each scenario k times; gate on a never-break suite.",
         "probes": ["What goes in the never-break suite?", "How do you build golden conversations?", "How many runs per scenario?"],
         "notes": ["Lex's Test Workbench builds test sets from existing transcripts and shows intent and slot performance against a bot."],
         "learn": R("w30", "cx_test", "p_tau", extra=[B("error-analysis", "error analysis", "Regression sets."), {"url": "commure.html#/prep/q-how-do-you-evaluate-a-voice-agent", "label": "Commure page: how you evaluate a voice agent", "why": "Your three layers for voice, already written."}, {"url": "../BASELINE.html#/ai/evaluation", "label": "Baseline: evaluation", "why": "The core topic."}])},
    ]},

    {"group": "NLP and text classification", "blurb": "The map of the field, then classification at depth: the ladder, metrics, out-of-scope, imbalance, calibration, latency. Taught in wc25 and wc26.", "items": [
        {"q": "Give me the map of NLP in two minutes.", "short": "The map",
         "tests": "Breadth: where everything sits, and why it moved.",
         "a": ["I think of it in three layers. Representations: one-hot, bag of words and TF-IDF, then static embeddings like word2vec, then contextual ones from BERT, and sentence embeddings on top. Tasks: classification, sequence labelling like NER, question answering, summarisation, translation, retrieval, dialogue, information extraction. And how it's evaluated: precision and recall, BLEU and ROUGE, perplexity, and now human and LLM judges.",
               "The eras go rules, then statistical models on hand-built features, Naive Bayes, logistic regression, HMMs and CRFs, then neural sequence models with attention, then the Transformer in 2017. BERT made pretrain-then-fine-tune standard, and scaling decoders gave us LLMs that do most tasks from a prompt. Each step replaced feature engineering with learned representations.",
               "Conversational AI is a stack over that map: intent classification and NER in front, retrieval for knowledge, an LLM for generation and tool calls, plus state and evaluation. In most assistants I've seen, classification and embeddings sit in front of the LLM as routers and guards."],
         "land": "Representations, tasks, evaluation; rules to statistics to neural to Transformers to LLMs; assistants are a stack over it.",
         "probes": ["Where are rules still the right answer?", "What did attention fix in seq2seq?", "Is perplexity a quality metric?"],
         "parts": [{"title": "Model eras",
                    "items": ["**Rules and regexes:** precise and brittle; still right for narrow, high-precision cases like IDs.", "**Statistical:** Naive Bayes, logistic regression, HMMs, CRFs, n-gram language models.",
                              "**Neural:** RNN, LSTM, GRU; CNNs for text; seq2seq with attention, which removed the fixed-vector bottleneck.",
                              "**Transformers:** encoders (BERT, RoBERTa, DeBERTa), decoders (GPT, Llama), encoder-decoders (T5, BART).", "**LLMs:** large decoders, pretrained, then instruction- and preference-tuned."]}],
         "notes": ["Perplexity measures a language model, not task quality.", "At UIC your coursework included Advanced NLP; you built a Transformer from scratch for English-German translation."],
         "learn": R("w25", extra=[{"url": "../BASELINE.html#/nlp", "label": "Baseline: NLP and conversational AI", "why": "The whole field, by cluster."}, {"url": "https://huggingface.co/learn/llm-course/chapter1/2", "label": "Hugging Face LLM course: NLP and LLMs", "why": "A short orientation.", "m": 10}])},

        {"q": "Classify 200 intents with 50 examples each. What do you do?", "short": "200 intents, 50 each",
         "tests": "The ladder, with judgement about where to stop.",
         "a": ["Baseline first: TF-IDF and logistic regression, because it tells me how hard the problem really is in a few seconds of training. Then sentence embeddings with a logistic head, then SetFit or a fine-tuned small encoder. Ten thousand examples is plenty for fine-tuning.",
               "With 200 intents, similar ones will collide, so the confusion matrix matters more than the overall score: merge or clarify those. If latency allows, embedding kNN gets the top ten candidate intents and a reranker or an LLM picks among them.",
               "Stratified held-out test set, macro-F1 and per-intent recall, and a none class from day one. I'd only move up the ladder when the next rung measurably beats the one below on that test set."],
         "land": "TF-IDF baseline, embeddings plus a head, then SetFit or a small encoder; watch collisions; macro-F1.",
         "probes": ["Why start with TF-IDF?", "Fine-tuning hyperparameters?", "Multi-label instead?"],
         "parts": [{"title": "The ladder, cheapest first",
                    "items": ["**TF-IDF + logistic regression / linear SVM / Naive Bayes:** seconds, CPU, interpretable.", "**fastText:** word and subword n-grams with a linear layer; very fast.",
                              "**Frozen sentence embeddings + logistic head or kNN:** strong with little data, cheap to retrain, easy to add a class.", "**SetFit:** contrastive fine-tuning on pairs, then a head; competitive at 8 to 64 examples per class.",
                              "**Fine-tuned encoder (BERT, RoBERTa, DeBERTa; DistilBERT for speed):** best with hundreds to thousands per class. Typical: learning rate 2e-5 to 5e-5, batch 16 to 32, 2 to 4 epochs, warmup.",
                              "**Zero-shot NLI:** each label as a hypothesis; no data, slow, weak on fine-grained labels.", "**LLM prompting:** zero training, changing labels, cold start; latency and cost per call.",
                              "**LoRA-tuned LLM:** many examples, LLM quality, stable labels; often distilled later into an encoder."]},
                   {"title": "When to pick which",
                    "items": ["Under 50 examples and labels change often: LLM prompting or SetFit.", "50 to 500 per class, stable, tight latency: embeddings plus a head, or SetFit.",
                              "Thousands of examples, under about 20 ms: a fine-tuned small encoder.", "Hundreds of overlapping labels: retrieve candidate labels by embedding, then a reranker or LLM chooses."]}],
         "notes": ["The fine-tuning hyperparameters are typical values from memory in the research, not from a source: say 'typically'."],
         "swaps": [{"when": "If they ask about multi-label", "line": "Then it's a sigmoid per label with binary cross-entropy instead of one softmax, a threshold per label, and per-label F1. Subset accuracy only if the product needs every label right at once."}],
         "learn": R("w26", "slp4", "hf_cls", "setfit", extra=[B("text-classification", "text classification", "The ladder.")])},

        {"q": "TF-IDF: what does it do, and when is it still the right tool?", "short": "TF-IDF",
         "tests": "The classic baseline, understood, with a real use.",
         "a": ["It weights a term by how often it appears in a document times the inverse of how many documents contain it, usually the log of that. So 'the' counts for almost nothing, and a word that's frequent here but rare elsewhere counts a lot.",
               "It's still the right tool as a cheap, interpretable baseline for classification and for sparse retrieval, when vocabulary is the signal and the data is small: product codes, error messages, domain jargon. Where it fails is synonyms and word order, which is what dense embeddings fix.",
               "And they combine well. In MetaRAG we used TF-IDF weighted embeddings with recursive chunking, and that got 82.5% precision against a 73.3% baseline. I think hybrid sparse plus dense beats either alone more often than people expect."],
         "land": "Frequency here times rarity elsewhere; still the baseline and the sparse half of hybrid search.",
         "probes": ["How does BM25 differ?", "Why the log?", "How exactly did MetaRAG weight the embeddings?"],
         "notes": ["BM25 adds term-frequency saturation and document-length normalisation to the same idea.",
                   "Before Friday, check in the MetaRAG code or paper exactly how the TF-IDF weights enter the embedding, so you can say it in one sentence if asked. Don't guess on the call."],
         "learn": R("w25", "slp4", extra=[B("bow-tfidf", "bag of words and TF-IDF", "The sparse representations."), {"url": "../SYSTEM%20DESIGN.html#/patterns/search/hybrid-rerank", "label": "Guide: hybrid search and reranking", "why": "Sparse and dense together."}])},

        {"q": "How do you handle out-of-scope queries?", "short": "Out-of-scope",
         "tests": "Treating 'none of the above' as a first-class class.",
         "a": ["As a first-class case, not an afterthought. The CLINC150 paper showed classifiers do well on supported intents and poorly on out-of-scope ones, so it needs its own design.",
               "I'd add an explicit none class trained on real and synthetic off-topic queries, especially near misses like 'I want to buy a book' in a flight bot, plus greetings, bare yes and no, and bare numbers. Calibrate the confidence with temperature scaling and set a threshold that hits a target in-scope accuracy. Add an embedding-distance check, distance to the nearest class centroid, as a second signal, and send the borderline cases to an LLM or a person.",
               "And measure it properly: out-of-scope recall and the false-accept rate at a fixed in-scope accuracy, not overall accuracy, which hides it completely."],
         "land": "A trained none class with near misses, a calibrated threshold, a distance check, borderline to an LLM.",
         "probes": ["Max softmax is a weak signal: why?", "Where do you get out-of-scope examples?", "Why are LLMs better at it?"],
         "parts": [{"title": "Detectors, from simple up",
                    "items": ["**Max softmax with a threshold:** the baseline; needs calibration.", "**An explicit none class:** often the most reliable.", "**Distance to class centroids or kNN in embedding space;** Mahalanobis distance on features.",
                              "**Ensemble disagreement.**", "**An LLM judge** for the borderline band."]}],
         "notes": ["Platforms: CLU's None intent with a score threshold (not applied during evaluation); Dialogflow CX's default negative intent; Lex's AMAZON.FallbackIntent.",
                   "In the 2026 preprint the LLM's out-of-scope recall was 85.6 against 58.1 for the fine-tuned encoder: the main reason to route uncertain turns to one."],
         "learn": R("w26", "p_clinc", "p_calib", extra=[B("out-of-scope", "out-of-scope detection", "Detectors and how to measure them.")])},

        {"q": "Your classes are 100 to 1 imbalanced. What do you try, in order?", "short": "Imbalance",
         "tests": "Cheapest effective fix first, and the right metric.",
         "a": ["First fix the evaluation: macro-F1, per-class recall and precision-recall curves, because accuracy will look great while the rare class is ignored.",
               "Then class weights in the loss, the cheapest change. Then oversampling the rare class or undersampling the common one, on the training set only, never on validation or test. Then a per-class threshold tuned on validation to hit a target recall, which is often the highest-value fix of all. Focal loss if easy examples swamp training.",
               "And check the rare-class labels are clean, and collect more of them with active learning. Fixing a few percent of bad labels often beats a bigger model."],
         "land": "Fix the metric, then weights, resampling, per-class thresholds, focal loss; clean and collect the rare class.",
         "probes": ["Why not resample the test set?", "What does focal loss do?", "How does oversampling overfit?"],
         "notes": ["Oversampling duplicates can overfit to those exact examples.", "Focal loss (Lin et al., from object detection) down-weights easy examples so the rare, hard ones dominate the gradient."],
         "learn": R("w26", "p_focal", extra=[B("text-classification", "text classification", "Imbalance."), B("classification-metrics", "classification metrics", "Precision-recall curves.")])},

        {"q": "Macro or micro F1, and when does accuracy lie?", "short": "Metrics",
         "tests": "Choosing the metric that matches the product.",
         "a": ["Precision is 'of what I flagged, how much was right'; recall is 'of what was there, how much I found'; F1 is their harmonic mean. Micro-F1 pools every decision, so the big classes dominate. Macro-F1 averages per-class F1, so every class counts equally.",
               "Accuracy lies under imbalance. If 95% of traffic is one intent, a model that always predicts it scores 95% accuracy and near-zero macro-F1.",
               "For an assistant I'd report both averages plus per-intent recall, and weight by business cost where I can: missing a fraud report isn't the same as missing a greeting."],
         "land": "Micro pools, macro averages per class; accuracy lies under imbalance; report per-intent recall.",
         "probes": ["When would you prefer micro?", "Why the harmonic mean?", "What's a precision-recall trade-off in an assistant?"],
         "notes": ["Micro-F1 equals accuracy for single-label multi-class, which is why it hides rare classes."],
         "learn": R("w26", "clu_eval", extra=[B("classification-metrics", "classification metrics", "Macro, micro and the confusion matrix."), {"url": "../BASELINE.html#/ml/evaluation-splits", "label": "Baseline: evaluation and splits", "why": "Precision and recall in the ML field."}])},

        {"q": "Why does calibration matter, and how do you fix it?", "short": "Calibration",
         "tests": "Knowing that every routing rule depends on it.",
         "a": ["A model is calibrated if, when it says 80% confident, it's right about 80% of the time. Modern neural networks are overconfident; Guo and colleagues showed it in 2017. And every downstream rule, route, confirm, fall back, escalate, reads that confidence, so a miscalibrated model makes every threshold wrong.",
               "Measure it with a reliability diagram and expected calibration error. The cheap fix is temperature scaling: divide the logits by one scalar fitted on a validation set. It doesn't change any prediction, only the confidence.",
               "I'd recalibrate after every retrain. That's also why a platform's score isn't a probability: Lex says its scores are comparative, and CLU warns of wrong intents at 1.00."],
         "land": "Confidence must mean what it says; every threshold depends on it; temperature scaling, refitted each retrain.",
         "probes": ["Why are networks overconfident?", "What's ECE?", "Does temperature scaling change accuracy?"],
         "notes": ["ECE: bin predictions by confidence, then average the gap between confidence and accuracy in each bin, weighted by bin size."],
         "learn": R("w26", "p_calib", extra=[B("classification-metrics", "classification metrics", "Calibration."), B("out-of-scope", "out-of-scope detection", "Thresholds that depend on it.")])},

        {"q": "How would you reduce the latency of a BERT classifier?", "short": "BERT latency",
         "tests": "Practical serving, in order of effort.",
         "a": ["In order of effort: truncate the input to what you need, use dynamic padding and length-bucketed batching, export to ONNX or TensorRT, run in fp16 or int8, then distil into a smaller model like DistilBERT or MiniLM.",
               "Around that, cache frequent inputs, and use a cascade: a cheap model handles the confident cases and the big one only sees the rest.",
               "And measure p95 on the real hardware before and after. At UIC I deployed an audio model at 150 milliseconds p95 with INT8 quantisation, so I've done that step on real hardware."],
         "land": "Truncate and batch, export, quantise, distil; cache and cascade; measure p95 on real hardware.",
         "probes": ["What does int8 cost in accuracy?", "How does distillation work?", "Where does the time go in a BERT forward pass?"],
         "notes": ["Distillation trains a small student to match the big teacher's output probabilities, not only the labels."],
         "learn": R("w26", "weng_inf", extra=[B("text-classification", "text classification", "Serving."), {"url": "../BASELINE.html#/inference/quantization", "label": "Baseline: quantisation", "why": "What int8 changes."}])},

        {"q": "What is SetFit, and why does it work with so few examples?", "short": "SetFit",
         "tests": "A modern few-shot method, understood.",
         "a": ["SetFit fine-tunes a sentence transformer contrastively on pairs made from your few labelled examples, same class pulled together, different classes pushed apart, then trains a logistic head on the resulting embeddings.",
               "It works because a handful of examples per class makes a lot of pairs, and the encoder already starts with good semantics, so it only has to bend the space a little. No prompts, quick to train, and it's competitive with much bigger models at 8 to 64 examples per class.",
               "It's the classifier in the Amazon hybrid paper: SetFit handles the confident turns and the LLM the uncertain ones. For a new intent with little traffic, I think it's the first thing I'd try after a TF-IDF baseline."],
         "land": "Contrastive pairs on a sentence encoder, then a head; many pairs from few examples.",
         "probes": ["How many pairs from 8 examples per class?", "How does it compare to prompting an LLM?"],
         "learn": R("w26", "setfit", extra=[B("text-classification", "text classification", "Few-shot methods."), B("sentence-embeddings", "sentence embeddings", "The contrastive training it uses.")])},

        {"q": "Your model scores 92% on the test set but poorly in production. Why?", "short": "Test vs production",
         "tests": "Debugging the gap between offline and online.",
         "a": ["Most likely distribution shift: new phrasing, new users, a new product. Or the test set is flawed, with label noise or leakage from training. Or a prior shift, where the class balance in production differs from the test set.",
               "I'd sample production traffic, label it, and score the model on that. Compare embedding distributions between training and production to see the shift. And check preprocessing: a mismatch between how text is cleaned in training and in serving causes this more often than people admit.",
               "Then the fix is the loop: production samples into training, a time-based split so the test set looks like the future, and monitoring on the live mix. It's the same lesson as alfred_'s test set: cases from real production, not from what we imagined."],
         "land": "Shift, a flawed test set, or a prior shift; label production samples, compare distributions, check preprocessing.",
         "probes": ["How would you detect leakage?", "What's a time-based split?"],
         "learn": R("w26", extra=[B("text-classification", "text classification", "Data, leakage and shift."), B("error-analysis", "error analysis", "Production samples.")])},
    ]},

    {"group": "Embeddings", "blurb": "Why embeddings work, how sentence embeddings are trained, choosing a model, similarity, search and failure modes. Taught in wc26.", "items": [
        {"q": "Why do embeddings work?", "short": "Why they work",
         "tests": "The idea under every vector, in plain words.",
         "a": ["The distributional hypothesis: words used in similar contexts have similar meanings. Train a model to predict context and it's forced to put similar words near each other, so the geometry ends up encoding meaning. Nobody puts the meaning in; it falls out of the objective.",
               "Word2vec is the clean example. Skip-gram predicts the context words from the centre word. Instead of a softmax over the whole vocabulary, negative sampling turns it into a binary task: raise the score of the true pair, lower it for a few random words. That makes training cheap, and the learned vectors are the embeddings.",
               "Sentence embedding models extend the same idea with a contrastive objective: texts that should match are trained to be close."],
         "land": "Similar contexts, similar meanings; predicting context forces the geometry.",
         "probes": ["Skip-gram or CBOW?", "Why negative sampling?", "GloVe and fastText, how do they differ?"],
         "parts": [{"title": "Three static models",
                    "items": ["**word2vec (2013):** skip-gram or CBOW, negative sampling, subsampling of frequent words. Typical: 300 dimensions, window about 5.", "**GloVe (2014):** factorises a global co-occurrence matrix so dot products approximate log co-occurrence counts.",
                              "**fastText:** a word is the sum of its character n-gram vectors, so it handles rare words, typos and unseen words."]}],
         "figs": ["embed"],
         "learn": R("w26", "al_w2v", "slp5", extra=[B("word-embeddings", "word embeddings", "word2vec, GloVe, fastText."), {"url": "../BASELINE.html#/ml/embeddings", "label": "Baseline: embeddings (ML field)", "why": "The core topic."}])},

        {"q": "Static or contextual embeddings: what's the difference?", "short": "Static and contextual",
         "tests": "Why BERT changed things.",
         "a": ["Static embeddings give one vector per word type, so 'bank' has one vector whether it's a river or money. Contextual models, ELMo with a bidirectional LSTM and then BERT with a Transformer encoder, compute a vector per occurrence from the whole sentence, so the sense comes from context.",
               "Contextual vectors are better for most tasks, but they cost a model forward pass per input. Static ones are a lookup.",
               "For an assistant that matters for words like 'card', 'balance' or 'charge', which mean different things in different intents."],
         "land": "One vector per word versus one per occurrence; context resolves the sense.",
         "probes": ["What did ELMo add?", "When would you still use static vectors?"],
         "learn": R("w26", "al_bert", extra=[B("word-embeddings", "word embeddings", "Static versus contextual.")])},

        {"q": "Why can't you mean-pool BERT for sentence similarity?", "short": "Sentence embeddings",
         "tests": "How sentence embeddings are trained, at depth.",
         "a": ["Because BERT was trained to predict masked tokens, not to compare sentences. Its pooled vectors are anisotropic, packed into a narrow cone, so almost every cosine is high and the similarities don't line up well with meaning.",
               "Sentence-BERT fixed that by training a siamese BERT on sentence pairs so cosine works; it also took a search over 10,000 sentences from about 65 hours to about 5 seconds. The modern recipe is contrastive: pull a query and its positive together, push others apart, with the InfoNCE loss. In-batch negatives make every other example in the batch a free negative, so big batches help, and hard negatives, similar but wrong, help most.",
               "SimCSE showed even dropout noise works as the augmentation, unsupervised, and that contrastive training spreads the vectors out."],
         "land": "BERT wasn't trained to compare; contrastive training with in-batch and hard negatives makes cosine meaningful.",
         "probes": ["Write InfoNCE in words.", "What does temperature do in the loss?", "What's a hard negative for an intent classifier?"],
         "parts": [{"title": "InfoNCE in words",
                    "items": ["For each query: a softmax over its similarity to one positive and many negatives, each divided by a temperature.", "The loss is minus the log of the positive's share.",
                              "A low temperature (around 0.05 to 0.1, from memory) penalises hard negatives sharply."]}],
         "notes": ["Hard negatives for an assistant: utterances from the intent it's most often confused with."],
         "learn": R("w26", "p_sbert", "weng_con", extra=[B("sentence-embeddings", "sentence embeddings", "Contrastive training.")])},

        {"q": "How do you choose an embedding model?", "short": "Choosing a model",
         "tests": "A method, not a leaderboard rank.",
         "a": ["Shortlist from MTEB, filtered to the task and the language I need, retrieval or classification or clustering. Then check the practical things: maximum input length, dimension, licence, hosting, latency and price.",
               "Then the part that decides: build 100 to 300 real query-to-answer pairs from our own data and compare recall at k and MRR. Small gaps on a public leaderboard rarely survive on your own data.",
               "In MetaRAG the evaluation on our own queries is what found the win: TF-IDF weighted embeddings beat the plain baseline, 82.5% precision against 73.3%, with 0.925 Hit Rate at 10."],
         "land": "Shortlist from MTEB, check the practical limits, decide on your own labelled queries.",
         "probes": ["Which models would you shortlist today?", "What's MRR?", "What happens when you switch models?"],
         "notes": ["MTEB, in the original paper: 8 task types, 58 datasets, 112 languages; it has grown since. Check rankings live; don't quote them from memory.",
                   "Families to name: OpenAI text-embedding-3, Cohere, Voyage, Google's Gemini embeddings; open ones like BGE, E5, GTE, Nomic, Qwen. From memory: say 'families like'.",
                   "Switching models means re-embedding everything; vectors from two models aren't comparable."],
         "learn": R("w26", "p_mteb", "mteb_lb", extra=[B("sentence-embeddings", "sentence embeddings", "Choosing a model."), {"url": "mphasis.html#/prep/q-what-are-embeddings-and-how-does-similarity-search-work", "label": "Mphasis page: embeddings and similarity search", "why": "Your general answer, already written."}])},

        {"q": "Cosine, dot product or Euclidean distance?", "short": "Similarity",
         "tests": "Knowing they're often the same, and when they're not.",
         "a": ["Cosine is the dot product with the lengths divided out, so it ignores magnitude. On unit-normalised vectors, dot product equals cosine and gives the same ranking as Euclidean distance.",
               "So normalise once at write time and use the fastest, which is the dot product.",
               "The exception: if a model was trained with dot product and its vector length carries meaning, popularity for example, don't normalise blindly. Use the metric the model card says it was trained with."],
         "land": "Same ranking on normalised vectors; normalise once, use dot product; follow the model card.",
         "probes": ["Prove the L2 equivalence.", "When does magnitude matter?"],
         "notes": ["For unit vectors, squared distance is 2 minus 2 times the cosine, so ranking by one ranks by the other."],
         "figs": ["vectors"],
         "learn": R("w26", extra=[B("sentence-embeddings", "sentence embeddings", "Similarity."), {"url": "../CODING.html#embed", "label": "Coding page: embeddings and vector search", "why": "The code."}])},

        {"q": "HNSW, IVF and PQ: what are they, and when do you use each?", "short": "Vector search",
         "tests": "Approximate nearest neighbour search, practically.",
         "a": ["Flat search compares against every vector, fine up to roughly a million. HNSW is a layered proximity graph: you descend greedily from sparse top layers to the dense bottom one. Very good recall and speed, at high memory; the knobs are M, efConstruction and efSearch.",
               "IVF clusters the space with k-means and searches only the nearest few cells, which saves compute. PQ splits each vector into sub-vectors and stores a short code for each, 10 to 50 times less memory at some recall cost. IVF-PQ together is the billion-scale option.",
               "For an assistant's knowledge base, flat or HNSW is usually enough. I'd also use hybrid search, BM25 plus dense with rank fusion, which often beats dense alone; my Comments Probe project used a two-phase hybrid search."],
         "land": "Flat to a million, HNSW for recall and speed, IVF-PQ for billions; hybrid often beats dense alone.",
         "probes": ["What does efSearch trade?", "What are Matryoshka embeddings?", "How do filters interact with ANN?"],
         "swaps": [{"when": "If they ask about Matryoshka embeddings", "line": "The model is trained so the first k dimensions are a good embedding on their own, for several k. You can truncate to, say, 256 and renormalise to cut storage and search cost with a small quality drop, then rerank with the full vectors."}],
         "learn": R("w26", "faiss", "p_mrl", extra=[B("sentence-embeddings", "sentence embeddings", "Search."), {"url": "../BASELINE.html#/data/vector-db", "label": "Baseline: vector databases", "why": "The core topic."}, {"url": "../SYSTEM%20DESIGN.html#/patterns/search/vector", "label": "Guide: vector search", "why": "As a design technique."}])},

        {"q": "Where do embeddings fail, and how do you use them in an assistant?", "short": "Failures and uses",
         "tests": "Knowing the limits, and the practical uses.",
         "a": ["They're weak on negation, numbers and identifiers: 'I can't log in' and 'I can log in' sit close together. They miss domain vocabulary a general model never saw. Short queries against long passages need models trained with query and document prefixes. Chunking and truncation silently drop content. And upgrading the model means re-embedding everything.",
               "I'd mitigate with hybrid BM25, a cross-encoder reranker, domain fine-tuning with hard negatives, and a retrieval evaluation set in CI.",
               "In an assistant they do three jobs: intent detection by nearest labelled example or class centroid, clustering misses to find new intents, and retrieval for the knowledge answers. MetaRAG is my retrieval example: TF-IDF weighted embeddings, 0.925 Hit Rate at 10."],
         "land": "Negation, numbers, IDs, domain words, truncation; hybrid, rerankers, fine-tuning; three uses in an assistant.",
         "probes": ["How would you fix negation?", "What does a reranker add?", "When would you fine-tune an embedding model?"],
         "notes": ["A cross-encoder reads the query and the passage together, so it's slower but far better at the details embeddings blur, like negation."],
         "learn": R("w26", extra=[B("sentence-embeddings", "sentence embeddings", "Failure modes."), {"url": "../BASELINE.html#/ai/hybrid-search-reranking", "label": "Baseline: hybrid search and reranking", "why": "The core topic."}, {"url": "../SYSTEM%20DESIGN.html#/patterns/search/hybrid-rerank", "label": "Guide: hybrid search and reranking", "why": "As a design technique."}])},
    ]},

    {"group": "LLM fundamentals and the Transformer", "blurb": "Attention and the block, encoders and decoders, the KV cache, tokens, decoding, post-training, and fine-tune versus RAG. Taught in wc27; lightly.", "items": [
        {"q": "Explain attention to me.", "id": "q-attention", "short": "Attention",
         "tests": "The mechanism in plain words, with the intuition.",
         "a": ["Each token's vector is projected three ways: a query, a key and a value. The query is compared, by dot product, with every token's key to get scores; a softmax turns the scores into weights; and the token's new vector is the weighted sum of the values.",
               "The intuition: the query is 'what am I looking for', the key is 'what I contain', the value is 'what I hand over if chosen'. So every token gathers what's relevant from the whole sequence in one parallel step, where an RNN had to pass information along step by step.",
               "I built one from scratch, a Transformer for English-German translation following the original paper, so this is the part I'd be happiest to draw on a whiteboard."],
         "land": "Query against every key, softmax into weights, weighted sum of values; all positions in one parallel step.",
         "probes": ["Why divide by the square root of d_k?", "What's multi-head for?", "Self-attention versus cross-attention?"],
         "parts": [{"title": "The formula, said out loud",
                    "items": ["Attention(Q, K, V) = softmax(Q Kᵀ / √d_k) V.", "**Causal mask:** position i can't attend to j greater than i, so training is many next-token predictions at once.",
                              "**Cross-attention:** queries from the decoder, keys and values from the encoder (translation, T5)."]}],
         "figs": ["qkvAttention"],
         "learn": R("w27", "al_tf", "b1b_att", "raschka", extra=[B("attention", "attention", "The mechanism."), {"url": "../BASELINE.html#/ml/transformers", "label": "Baseline: Transformers and attention (ML field)", "why": "The core topic."}, {"url": "../CODING.html#transformer", "label": "Coding page: attention and a Transformer block", "why": "The code."}])},

        {"q": "Why divide the attention scores by the square root of d_k?", "short": "The √d_k",
         "tests": "A classic follow-up: do you know why, not only that?",
         "a": ["Because dot products grow with dimension. If the query and key entries have unit variance, their dot product over d_k dimensions has variance d_k.",
               "Large scores push the softmax into saturation, nearly one-hot, where the gradients are tiny and training stalls. Dividing by the square root of d_k brings the variance back to about one.",
               "So it's a variance fix to keep the softmax in the range where it can learn."],
         "land": "Dot-product variance grows with d_k; big scores saturate softmax and kill gradients; the root brings it back to one.",
         "probes": ["Why the square root and not d_k?", "What does a saturated softmax do to gradients?"],
         "notes": ["The square root because variance scales with d_k, so the standard deviation scales with its root."],
         "figs": ["attention"],
         "learn": R("w27", extra=[B("attention", "attention", "Scaling."), {"url": "../BASELINE.html#/ml/transformers", "label": "Baseline: Transformers and attention", "why": "The core topic."}])},

        {"q": "Why multiple heads, and how does position get in?", "short": "Heads and position",
         "tests": "Two standard follow-ups in one.",
         "a": ["Multiple heads run attention several times in parallel on smaller projections, d_k is d_model divided by the number of heads, then concatenate and project. Different heads can learn different relations, syntax, position, coreference, at the same total cost as one big head.",
               "Attention itself is order-blind, so position has to be injected. The original paper added fixed sine and cosine waves to the embeddings. BERT and GPT-2 learned a vector per position, capped at the training length. RoPE, the default in Llama-style models, rotates the query and key vectors by an angle that depends on position, so their dot product depends on relative distance, and it extends better to longer contexts."],
         "land": "Heads: several relations at the same cost. Position: sinusoidal, learned, or RoPE's rotation for relative distance.",
         "probes": ["Why does RoPE extend to longer context?", "What do heads actually learn?"],
         "learn": R("w27", "al_tf", "p_rope", extra=[B("attention", "attention", "Heads and positions.")])},

        {"q": "Walk me through one Transformer block.", "short": "The block",
         "tests": "The whole layer, lightly, and where the parameters are.",
         "a": ["Normalise, attend, add the input back; normalise, run a feed-forward network on each token, add back again. That block repeats N times.",
               "The residual connections, x plus the sublayer of x, keep gradients flowing through deep stacks. Layer norm normalises each token's activations. The original put the norm after the residual add, post-LN, which needs learning-rate warmup; modern LLMs put it before each sublayer, pre-LN, which trains stably without it, and many use RMSNorm.",
               "The feed-forward block expands to about four times the width, applies a nonlinearity and projects back. It holds about two-thirds of the parameters and is where a lot of factual knowledge is thought to live."],
         "land": "Norm, attend, add; norm, feed-forward, add; repeated; the FFN holds two-thirds of the parameters.",
         "probes": ["Pre-LN or post-LN, and why?", "Roughly how many parameters per layer?", "Why is attention O(n²)?"],
         "parts": [{"title": "Rough numbers",
                    "items": ["About 12 × d_model² parameters per layer: 4 d² in attention, 8 d² in a 4× FFN.", "GPT-3: 96 layers, d_model 12,288, about 174B by that formula; published 175B.",
                              "BERT-base: 12 layers, 768 hidden, 12 heads, about 110M (from memory).", "Training compute is about 6 × parameters × tokens; inference about 2 × parameters per token."]},
                   {"title": "Why O(n²), and what helps",
                    "items": ["Every token is scored against every other, so time and memory grow with the square of the length.", "FlashAttention keeps it exact and cuts memory traffic by tiling.",
                              "Sparse or windowed attention restricts the pattern; the KV cache avoids recomputation during generation."]}],
         "figs": ["transformerBlock"],
         "learn": R("w27", "p_preln", "b1b_mlp", extra=[B("encoders-decoders", "encoders and decoders", "The block in each family."), {"url": "../CODING.html#transformer", "label": "Coding page: attention and a Transformer block", "why": "The code."}])},

        {"q": "BERT versus GPT: what's the difference?", "short": "BERT and GPT",
         "tests": "Encoders, decoders, and which to use for what.",
         "a": ["BERT is an encoder trained on masked-token prediction: hide about 15% of the tokens and predict them from both sides. So it builds rich representations, good for classification, NER, embeddings and reranking, but it can't generate fluently.",
               "GPT is a decoder trained to predict the next token with a causal mask, so it only sees the left context and it generates naturally. T5 and BART are the third family, encoder-decoders, where the encoder reads the input and the decoder generates while attending to it: translation, summarisation.",
               "Instruction-tuned decoders now do classification too, by prompting, but for pure understanding at volume an encoder is still much cheaper and faster. That's the whole classic-versus-LLM trade-off in an assistant."],
         "land": "Encoder, both directions, understanding; decoder, left to right, generation; encoders still win on cost for classification.",
         "probes": ["Why can't BERT generate?", "Which would you use for intent classification?", "What's span corruption?"],
         "notes": ["T5's span corruption masks spans and generates the missing ones."],
         "learn": R("w27", "al_bert", "hf_arch", "slp9", extra=[B("encoders-decoders", "encoders and decoders", "The three families."), {"url": "mphasis.html#/prep/q-how-does-a-large-language-model-work", "label": "Mphasis page: how an LLM works", "why": "Your general answer, already written."}])},

        {"q": "What is the KV cache, and why does it matter?", "short": "KV cache",
         "tests": "Inference cost, from the mechanism.",
         "a": ["During generation, the keys and values of past tokens don't change, so you store them. Each new token computes only its own query, key and value and attends over the cache, instead of recomputing the whole sequence.",
               "The cache grows with layers, context length and batch size, and at long context it often dominates GPU memory. For a 7B Llama-style model, 32 layers and hidden size 4096 in fp16, that's two tensors times 32 layers times 4096 times 2 bytes, about half a megabyte per token, so 4,000 tokens is about 2 GB per sequence.",
               "That's why long context and high concurrency are expensive, and why grouped-query attention shares keys and values across heads to shrink it."],
         "land": "Store past keys and values; it grows with layers, context and batch; GQA shrinks it.",
         "probes": ["What's prefill versus decode?", "How does GQA work?", "Why is decode memory-bound?"],
         "notes": ["The half megabyte is arithmetic: 2 (K and V) × 32 layers × 4,096 × 2 bytes = 524,288 bytes per token, assuming no GQA."],
         "learn": R("w27", "weng_inf", "p_gqa", extra=[{"url": "../BASELINE.html#/inference/kv-cache", "label": "Baseline: KV cache", "why": "The core topic."}, {"url": "../BASELINE.html#/inference/prefill-decode", "label": "Baseline: prefill and decode", "why": "Why decode is memory-bound."}])},

        {"q": "Why subword tokenization, and how does BPE work?", "short": "Tokenization",
         "tests": "Where cost and quirks begin.",
         "a": ["Word vocabularies explode and can't represent unseen words; characters make sequences very long. Subwords sit between: a fixed vocabulary, 30 thousand to a couple of hundred thousand, that composes any word from pieces.",
               "BPE starts from characters or bytes and repeatedly merges the most frequent adjacent pair; encoding replays those merges in the order they were learned. Byte-level BPE, in GPT-2 and RoBERTa, starts from the 256 bytes, so nothing is ever out of vocabulary. BERT's WordPiece is similar but picks merges by likelihood and marks continuations with '##'; SentencePiece treats spaces as characters, so it needs no language-specific pre-tokeniser.",
               "It matters in practice: token count drives cost and context, and tokenisation explains odd behaviour on spelling, arithmetic, IDs and other languages. In an assistant, account numbers split into odd pieces, which is one more reason to extract them with code."],
         "land": "Subwords: fixed vocabulary, any word; BPE merges frequent pairs; it drives cost and odd failures.",
         "probes": ["WordPiece versus BPE?", "Why do LLMs struggle to count letters?", "What's a unigram tokeniser?"],
         "figs": ["bpeMerge"],
         "learn": R("w27", "hf_bpe", "slp2", extra=[B("tokenization", "tokenization", "BPE, WordPiece, SentencePiece."), {"url": "../CODING.html#bpe", "label": "Coding page: a tokenizer, byte-pair encoding", "why": "The code."}])},

        {"q": "Temperature, top-k and top-p: what are they, and when do you use each?", "short": "Decoding",
         "tests": "Knowing which knob for which task.",
         "a": ["Temperature divides the logits before the softmax: below one sharpens the distribution, above one flattens it, and near zero it approaches greedy. Top-k samples from the k most likely tokens. Top-p, nucleus sampling, samples from the smallest set whose probabilities add up to p, so it adapts to how confident the model is.",
               "Greedy and beam search are deterministic. Beam is good for translation and summarisation but goes bland and repetitive on open-ended text; that's what the nucleus sampling paper was about.",
               "For classification, extraction and anything an assistant acts on, temperature zero or constrained decoding to a schema. Higher temperature with top-p only where variety is the point."],
         "land": "Temperature reshapes, top-k and top-p truncate; zero or constrained for anything the assistant acts on.",
         "probes": ["Why does top-p adapt better than top-k?", "Is temperature zero deterministic?", "What's constrained decoding?"],
         "notes": ["Temperature zero is close to deterministic but not guaranteed across providers and batches; don't promise byte-identical output."],
         "learn": R("w27", "p_nucleus", extra=[B("decoding", "decoding", "Greedy, beam, sampling.")])},

        {"q": "How does a pretrained model become an assistant?", "short": "Post-training",
         "tests": "Pretraining, SFT and preference tuning, in order.",
         "a": ["Pretraining on next-token prediction gives a model that continues text. Supervised instruction tuning on instruction and response pairs teaches it the format and to follow instructions; it gains behaviour more than knowledge.",
               "Then preference tuning. RLHF collects human rankings, trains a reward model, and optimises the policy with PPO plus a penalty for drifting from the tuned model; InstructGPT's 1.3B model was preferred over the 175B GPT-3. DPO skips the reward model and the RL loop and trains directly on preferred versus rejected pairs; it's simpler and more stable, and widely used.",
               "Scaling, in one line: loss falls as a power law in parameters, data and compute, and Chinchilla showed many early models were undertrained for their size."],
         "land": "Pretrain, then SFT for behaviour, then RLHF or DPO for preferences.",
         "probes": ["Why does SFT on unknown facts cause hallucination?", "DPO or RLHF?", "What's in-context learning?"],
         "notes": ["Weng's survey: fine-tuning on facts the model doesn't know teaches it to guess.", "In-context learning: the model adapts from examples in the prompt with no weight updates; choose examples by embedding similarity."],
         "learn": R("w27", "slp8", "p_instruct", "p_dpo", extra=[B("llm-training", "LLM training", "Pretraining to assistant."), {"url": "../BASELINE.html#/ml/preference-tuning", "label": "Baseline: preference tuning", "why": "The core topic."}])},

        {"q": "Fine-tune, LoRA, prompt or RAG: how do you choose?", "short": "Fine-tune or RAG",
         "tests": "Matching the method to the problem, for an assistant.",
         "a": ["Prompting first: fast, no training. RAG when the problem is knowledge that's private, large or changing, which in an assistant is policies, product details, help articles. Fine-tuning when the problem is behaviour, format, tone, a narrow skill, or latency and cost at scale.",
               "LoRA is how I'd fine-tune: freeze the base and train small low-rank matrices beside the weights, up to 10,000 times fewer trainable parameters than full fine-tuning in the paper, with no extra latency once merged, and adapters you can swap.",
               "The rule I use: knowledge goes in retrieval, behaviour goes in tuning, and try prompting before either. For an intent classifier specifically, a common pattern is to label with an LLM, then distil into a small encoder."],
         "land": "Knowledge in retrieval, behaviour in tuning, prompting first; LoRA for cheap fine-tunes.",
         "probes": ["How do you reduce hallucination in production?", "What's QLoRA?", "When would you fine-tune for an assistant?"],
         "swaps": [{"when": "If they ask about hallucination", "line": "Ground answers in retrieved evidence with citations, constrain the model to that context, use tools for facts and arithmetic, allow 'I don't know', and measure faithfulness on a regression set. At alfred_ we went further for one case: the model picks from real items and code attaches the ids, so it can't invent a thread at all."}],
         "learn": R("w27", "p_lora", "weng_hal", extra=[B("nlu-llm-hybrid", "classic NLU and LLMs together", "Where each fits."), {"url": "mphasis.html#/prep/q-prompting-rag-or-fine-tuning-when-do-you-use-which", "label": "Mphasis page: prompting, RAG or fine-tuning", "why": "Your general answer, already written."}, {"url": "mphasis.html#/prep/q-how-do-you-reduce-hallucination", "label": "Mphasis page: reducing hallucination", "why": "Already written."}, {"url": "../CODING.html#lora", "label": "Coding page: LoRA", "why": "The code."}])},
    ]},

    {"group": "Your work, mapped to the role", "blurb": "What you've built that matches, and the gaps said plainly.", "items": [
        {"q": "How does your background fit this role?", "short": "The fit",
         "tests": "Is it real, and are you honest about the gaps?",
         "a": ["Most of it maps directly. The role is building and improving virtual assistants, conversation design, intents and entities, error analysis, production improvements, on top of strong NLP. At alfred_ every message goes through intent classification and a decision layer before any tool runs, for 5,000-plus active users, and I built the scanner and eval harness that find and fix its failures from real conversations.",
               "What I haven't done is ship on a classic NLU platform like Dialogflow CX or Cognigy, or run a taxonomy of hundreds of intents, and I'd rather say that plainly. The modelling and the error analysis are the same work; the platform is new."],
         "land": "The assistant, the NLU in front of it and the error analysis: done. The classic platforms: new, said first.",
         "probes": ["How quickly could you ramp up on our platform?", "What's the biggest gap?"],
         "parts": [{"title": "Where you've done each area",
                    "items": ["**Intent classification and routing:** alfred_'s 'intent classification → decision layer → callable tools'.", "**Clarify and confirm by rule:** five verdicts, silent, notify, confirm, clarify, refuse, by deterministic risk scoring.",
                              "**Error analysis:** the production failure scanner; eval cases from real failures; the multi-turn rewrite signed off on them.", "**Flows and state:** MockFlow-AI's state machine, stages moved only by a tool call.",
                              "**Voice:** alfred_'s voice agent; MockFlow-AI under 400 ms with Deepgram Nova-2 and Silero VAD.", "**Embeddings and retrieval:** MetaRAG, TF-IDF weighted embeddings, 82.5% precision vs 73.3%, 0.925 Hit@10, 25% hallucination reduction, p99 under 300 ms at 10K queries a day.",
                              "**Transformers:** a from-scratch Transformer for English-German translation; Advanced NLP at UIC.", "**Cost:** per-user LLM cost cut about 30% with a deterministic matcher in place of per-message model calls."]},
                   {"title": "Not done yet: say so",
                    "items": ["Dialogflow CX, Lex, CLU, Rasa, Kore.ai or Cognigy in production.", "An intent taxonomy in the hundreds, with a team adding to it.", "Contact-centre analytics at enterprise volume: containment and CSAT across millions of sessions."]}],
         "learn": R("w29", "w30")},

        {"q": "Tell me about the decision layer at alfred_.", "short": "The decision layer",
         "tests": "Depth on your closest work.",
         "a": ["Every inbound message, by text or the web, is routed through intent classification, then a decision layer, then callable tools. The decision layer is where the assistant decides what to do with each candidate action.",
               "It classifies every candidate action into one of five verdicts: silent, notify, confirm, clarify or refuse. And it does that by deterministic risk scoring, not by asking an LLM to judge. I think that's the right split: the model is good at understanding what someone meant; whether it's safe to send an email on their behalf should be a rule you can test.",
               "It's the same three-band idea the platforms use for thresholds, act, confirm, fall back, applied to actions instead of intents. And because it's deterministic, every verdict can be tested and replayed."],
         "land": "Intent, then five verdicts by deterministic risk scoring, then tools; the model understands, rules decide.",
         "probes": ["What goes into the risk score?", "Why not an LLM judge?", "How do you test it?", "What happens on clarify?"],
         "notes": ["From the master reference: 'every candidate action classified into five verdicts (SILENT / NOTIFY / CONFIRM / CLARIFY / REFUSE) via deterministic risk scoring, not LLM-as-judge'.",
                   "The Coframe page says 'no risk score; a code floor confirms every send and irreversible delete'. Check which matches today's code, and what goes into the score, before Friday. If you're unsure on the call, describe the verdicts and the code floor, and leave the scoring detail out."],
         "never": ["Don't invent the inputs to the risk score."],
         "learn": R("w28", extra=[B("nlu-llm-hybrid", "classic NLU and LLMs together", "The model proposes, code decides.")])},

        {"q": "Tell me about the production failure scanner.", "short": "The failure scanner",
         "tests": "Error analysis you've actually run.",
         "a": ["It scans real production conversations, classifies genuine failures versus expected behaviour, and auto-promotes the real bugs for triage. The hard part is the second step: a lot of what looks like failure is the assistant correctly declining, or the user changing their mind.",
               "The genuine ones become cases in our eval harness, a little over a hundred so far, each running the real agent against a frozen copy of that user's world. So every change runs against what users actually hit before it ships; that's how we signed off a full rewrite of the agent.",
               "It's pretty much the transcript-review loop this role describes, automated: find the failures, label the cause, turn each into a test."],
         "land": "Real conversations, failure versus expected behaviour, real bugs promoted, each one a test case.",
         "probes": ["How does it tell failure from expected behaviour?", "How often does it run?", "What did it find that you didn't expect?"],
         "notes": ["From the master reference: 'scans real production conversations, classifies genuine failures vs. expected behavior, auto-promotes real bugs for triage'. The Coframe page says it runs daily."],
         "learn": R("w30", extra=[B("error-analysis", "error analysis", "The same loop, by hand."), {"url": "coframe.html#/prep/say-now", "label": "Coframe page: what you're working on now", "why": "The eval harness story, already written."}])},

        {"q": "Tell me about MetaRAG.", "short": "MetaRAG",
         "tests": "Your NLP research, with its numbers.",
         "a": ["MetaRAG was a retrieval framework for enterprise knowledge at UIC, accepted at IEEE CAI 2026. The finding I'd lead with: recursive chunking with TF-IDF weighted embeddings got 82.5% precision against a 73.3% baseline, and 0.925 Hit Rate at 10.",
               "It ran in a production code-translation use case at about 10K queries a day with p99 latency under 300 milliseconds, and it reduced hallucination by 25%.",
               "The lesson that carries over to an assistant: get retrieval right before touching the generation, and let sparse signals like TF-IDF help dense embeddings on domain vocabulary."],
         "land": "TF-IDF weighted embeddings and recursive chunking: 82.5% vs 73.3%, 0.925 Hit@10, 25% less hallucination.",
         "probes": ["How did the TF-IDF weighting work?", "What's Hit Rate at 10?", "How did you measure hallucination?"],
         "notes": ["Metrics verbatim from the master reference: 82.5% precision vs 73.3% baseline; 0.925 Hit Rate@10; 25% hallucination reduction; 10K queries/day; p99 under 300ms.",
                   "Check the weighting mechanism and how hallucination was measured in the paper before Friday; don't improvise either."],
         "learn": R("w26", extra=[B("bow-tfidf", "bag of words and TF-IDF", "The sparse half."), {"url": "../BASELINE.html#/ai/rag", "label": "Baseline: RAG", "why": "The core topic."}])},

        {"q": "Tell me about a time you improved an assistant from production data.", "short": "An improvement from production",
         "tests": "Root cause over symptom, with a result.",
         "a": ["Our assistant tracks what people owe others from their inbox. The model kept inventing email threads, or getting who owes whom backwards, which is the worst thing an assistant can do to trust.",
               "Instead of prompting harder, I changed the design: the model only picks from a list of real items and writes the sentence, and code attaches the real ids. That made a whole class of hallucination structurally impossible, not probabilistically reduced, and tests enforce it.",
               "Two smaller ones from the same habit: replacing per-message model calls with a deterministic matcher for email rules cut per-user LLM cost about 30%, and triggering notifications on the event instead of a timer took them from about 90 seconds to about 3."],
         "land": "Make the mistake impossible by design; then cost and latency from the same habit.",
         "probes": ["How did you find it?", "How do you know it's fixed?", "What would you do on a classic platform?"],
         "swaps": [{"when": "If they ask what that means on a classic platform", "line": "The same move as validating a slot against the system of record instead of trusting the extractor: the model understands, code supplies the facts."}],
         "learn": R("w30")},

        {"q": "You haven't used our platform. How would you get productive?", "short": "Ramping up",
         "tests": "Honesty plus a credible plan.",
         "a": ["Honestly, the platform is the part I'd learn; the work underneath it I've done. In the first week I'd read the intent taxonomy and the confusion matrix, sit with a few hundred real transcripts, and map the platform's pieces onto what I know: a page with a form is a state with required slots, a route is a transition, an event handler is the no-match ladder.",
               "Then I'd pick one small, measurable problem, a pair of confused intents or a page with a high no-match rate, and fix it end to end through the platform's test cases and release process. That teaches the platform on real work.",
               "That's how I work with any new stack: I built MockFlow-AI on LiveKit from scratch, and it runs under 400 milliseconds end to end."],
         "land": "Learn the platform on real work: taxonomy, transcripts, one small measurable fix end to end.",
         "probes": ["Which platform would be hardest for you?", "What would you need from the team?"],
         "learn": R("w29", extra=[B("intents-entities", "intents and entities", "Platform terms side by side.")])},
    ]},
]

